+                    if (vectorValues == null) {
+                        continue;
+                    }
+                    totalSize += vectorValues.size();
+                    StoredFields storedFields = ctx.reader().storedFields();
+                    int docId;
+                    while ((docId = vectorValues.nextDoc()) != NO_MORE_DOCS) {
+                        byte[] v = vectorValues.vectorValue();
