+public class GoogleVertexAiEmbeddingsAction implements ExecutableAction {
+
+    private final String failedToSendRequestErrorMessage;
+
+    private final GoogleVertexAiEmbeddingsRequestManager requestManager;
+
+    private final Sender sender;
+
+    public GoogleVertexAiEmbeddingsAction(Sender sender, GoogleVertexAiEmbeddingsModel model, ServiceComponents serviceComponents) {
+        Objects.requireNonNull(serviceComponents);
+        Objects.requireNonNull(model);
+        this.sender = Objects.requireNonNull(sender);
+        this.requestManager = new GoogleVertexAiEmbeddingsRequestManager(
+            model,
+            serviceComponents.truncator(),
+            serviceComponents.threadPool()
+        );
+        this.failedToSendRequestErrorMessage = constructFailedToSendRequestMessage(model.uri(), "Google Vertex AI embeddings");
+    }
+
+    @Override
+    public void execute(InferenceInputs inferenceInputs, TimeValue timeout, ActionListener<InferenceServiceResults> listener) {
+        try {
+            ActionListener<InferenceServiceResults> wrappedListener = wrapFailuresInElasticsearchException(
+                failedToSendRequestErrorMessage,
+                listener
+            );
+
+            sender.send(requestManager, inferenceInputs, timeout, wrappedListener);
+        } catch (ElasticsearchException e) {
+            listener.onFailure(e);
+        } catch (Exception e) {
+            listener.onFailure(createInternalServerError(e, failedToSendRequestErrorMessage));
+        }
+    }
+}

