+
+    /**
+     * Parses the Google Vertex AI get embeddings response.
+     * For a request like:
+     *
+     * <pre>
+     *     <code>
+     *         {
+     *             "inputs": ["Embed this", "Embed this, too"]
+     *         }
+     *     </code>
+     * </pre>
+     *
+     * The response would look like:
+     *
+     * <pre>
+     *     <code>
+     *         {
+     *           "predictions": [
+     *              {
+     *                "embeddings": {
+     *                  "statistics": {
+     *                    "truncated": false,
+     *                    "token_count": 6
+     *                  },
+     *                  "values": [ ... ]
+     *                }
+     *              }
+     *           ]
+     *         }
+     *     </code>
+     * </pre>
+     */
+
